// BarOps on Cloudflare Workers.
// Static assets are embedded (assets.js, generated by scripts/build-worker.js).
// All /api/* requests go to a single Durable Object that holds the database in
// memory and persists it to its built-in SQLite storage, so writes are consistent.
import { DurableObject } from 'cloudflare:workers';
import { createApp } from './core.js';
import { ASSETS } from './assets.js';

const CHUNK = 1024 * 1024; // store the JSON database in 1 MB rows

export class BarOpsDB extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    const sql = ctx.storage.sql;
    sql.exec('CREATE TABLE IF NOT EXISTS chunks (i INTEGER PRIMARY KEY, v TEXT NOT NULL)');
    this.app = createApp({
      load() {
        const rows = sql.exec('SELECT v FROM chunks ORDER BY i').toArray();
        return rows.length ? JSON.parse(rows.map((r) => r.v).join('')) : null;
      },
      save(db) {
        const s = JSON.stringify(db);
        const n = Math.max(1, Math.ceil(s.length / CHUNK));
        ctx.storage.transactionSync(() => {
          for (let i = 0; i < n; i++) sql.exec('INSERT OR REPLACE INTO chunks (i, v) VALUES (?, ?)', i, s.slice(i * CHUNK, (i + 1) * CHUNK));
          sql.exec('DELETE FROM chunks WHERE i >= ?', n);
        });
      },
    }, { secureCookies: true });
  }

  async fetch(request) {
    return this.app.handle(request, { ip: request.headers.get('cf-connecting-ip') || '' });
  }
}

const SECURITY_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Strict-Transport-Security': 'max-age=31536000',
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.protocol === 'http:') { url.protocol = 'https:'; return Response.redirect(url.toString(), 301); }
    if (url.pathname.startsWith('/api/')) {
      const stub = env.DB.get(env.DB.idFromName('main'));
      return stub.fetch(request);
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
    let p = url.pathname === '/' ? '/index.html' : url.pathname;
    let asset = ASSETS[p];
    if (!asset && !/\.[a-z0-9]+$/i.test(p)) asset = ASSETS['/index.html']; // SPA fallback
    if (!asset) return new Response('Not found', { status: 404, headers: SECURITY_HEADERS });
    return new Response(request.method === 'HEAD' ? null : asset.body, {
      headers: { 'Content-Type': asset.type, 'Cache-Control': 'no-cache', ...SECURITY_HEADERS },
    });
  },
};
